// M08-J03 acceptance 1: secret scans prove keys do not enter project files, exports, backups, receipts, AI records, logs, shared data or API responses.
//
// A recognisable fake key (sk-test-...) is set for a chat profile and for an image profile, and a webhook is created (its signing secret is generated by the server and shown once).
// A full session then runs against a mock provider: preview, send (whole and streamed), a rewrite, accept, AI records and the usage table on, cover generation and "Use as cover",
// a webhook delivery, an export in every format (and with provenance), and a backup with provenance. Afterwards every file under the library, every export and backup (unzipped,
// docx and epub too), the server's stdout / stderr, every API response the session saw, the user config folder and (shared mode) the shared-data folder is searched for each secret,
// in plain text, base64, hex and URL-encoded form. The runs cover every storage the platform supports (the native secure backend, the encrypted-file backend with a key file and
// with STORYFORGE_SECRETS_KEY, session memory, and the plain-text config file), so the scan is the same for each.
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { AI, ARRIVAL, BOOK, freshLibrary, getScene, makeHome, readConfigFiles, readEverything, startApp, stopAll } from './ai-helpers.mjs';
import { boot as bootShared, closeAll as closeShared } from './shared-helpers.mjs';
import { closeMocks, fakeKey, filesHolding, getBytes, holds, recording, startProvider, startReceiver, until, zipContents } from './j03-helpers.mjs';
import { randomBytes } from 'node:crypto';

after(async () => {
  await stopAll();
  await closeMocks();
  await closeShared();
});

const FORMATS = ['markdown', 'docx', 'epub', 'pdf'];
const TARGET = 'The ferry nudged the jetty and [[tobin-reyes|the ferryman]] threw her bag ashore.';
const REWRITTEN = 'The ferry bumped the jetty, and the ferryman flung her bag ashore.';

const RUNS = [
  { name: 'native secure backend (DPAPI on Windows, keychain / Secret Service when present, else the encrypted file)', storage: 'secure', env: {}, native: true },
  { name: 'secure, encrypted-file backend with its key file', storage: 'secure', env: { STORYFORGE_SECRETS_BACKEND: 'file-key' }, alg: 'aes-256-gcm', keyFile: true },
  { name: 'secure, encrypted-file backend with STORYFORGE_SECRETS_KEY', storage: 'secure', env: { STORYFORGE_SECRETS_BACKEND: 'file-key', STORYFORGE_SECRETS_KEY: randomBytes(32).toString('base64') }, alg: 'aes-256-gcm', keyFile: false },
  { name: 'session (memory only)', storage: 'session', env: { STORYFORGE_SECRETS_BACKEND: 'file-key' } },
  { name: 'config (plain text, in the user settings file only)', storage: 'config', env: { STORYFORGE_SECRETS_BACKEND: 'file-key' } },
];

async function fullSession(run) {
  const KEY = fakeKey('chat');
  const KEY_IMG = fakeKey('image');
  const library = await freshLibrary();
  const home = await makeHome();
  const chat = await startProvider({ reply: REWRITTEN });
  const pictures = await startProvider();
  const receiver = await startReceiver();
  const app = recording(await startApp({ library, home, env: run.env }));
  const secrets = [KEY, KEY_IMG];

  // ---- set up: a chat profile, an image profile, a webhook, records and usage on
  const mk = (body) => app.post(AI.profiles, body);
  const c1 = await mk({ name: 'Chat', kind: 'openai-compatible', model: 'mock-model-a', baseUrl: chat.baseUrl, keyStorage: run.storage, apiKey: KEY });
  assert.equal(c1.status, 201, c1.text);
  const c2 = await mk({ name: 'Pictures', kind: 'openai-compatible-images', model: 'image-1', baseUrl: pictures.baseUrl, keyStorage: run.storage, apiKey: KEY_IMG });
  assert.equal(c2.status, 201, c2.text);
  for (const c of [c1, c2]) assert.equal(c.json.profile.hasKey, true);
  assert.equal((await app.put(AI.bookProfile(), { profileId: c1.json.profile.id })).status, 200);
  assert.equal((await app.put(AI.bookProfile(), { profileId: c2.json.profile.id })).status, 200);
  assert.equal((await app.put(`/api/books/${BOOK}/ai/records`, { enabled: true })).status, 200);
  assert.equal((await app.put(`/api/books/${BOOK}/ai/records`, { usage: true })).status, 200);
  const hook = await app.post('/api/webhooks', { url: receiver.url, events: ['scene.saved', 'export.done', 'backup.done'], books: 'all' });
  assert.equal(hook.status, 201, hook.text);
  const WEBHOOK_SECRET = hook.json.secret;
  const createResponse = app.seen.at(-1);
  secrets.push(WEBHOOK_SECRET);

  // ---- chat: preview, send (whole), send again streamed
  const pv = await app.post(AI.context(), { task: 'chat', files: ['book.md'], instruction: 'Summarise the book.' });
  assert.equal(pv.status, 200, pv.text);
  assert.equal(chat.calls.length, 0, 'a preview sends nothing');
  const sent = await app.post(AI.send(), { contextId: pv.json.contextId });
  assert.equal(sent.status, 200, sent.text);
  const streamed = await app.post(AI.send(), { contextId: pv.json.contextId, stream: true });
  assert.equal(streamed.status, 202, streamed.text);
  await until(async () => (await app.get(`/api/books/${BOOK}/ai/stream?context=${pv.json.contextId}&from=0`)).json?.state === 'done', 'the streamed reply');

  // ---- rewrite, accept
  const scene = await getScene(app, ARRIVAL);
  const from = scene.body.indexOf(TARGET);
  const rp = await app.post(AI.context(), { task: 'rewrite', files: [], selection: { sceneId: scene.id, from, to: from + TARGET.length }, instruction: 'Tighten.' });
  assert.equal(rp.status, 200, rp.text);
  assert.equal((await app.post(AI.send(), { contextId: rp.json.contextId })).status, 200);
  assert.equal((await app.post(AI.apply(), { contextId: rp.json.contextId })).status, 200);

  // ---- cover generation, use as cover
  const info = await app.get(`/api/books/${BOOK}/ai/cover`);
  assert.equal(info.json.available, true, info.text);
  const gen = await app.post(`/api/books/${BOOK}/ai/cover-generate`, { prompt: info.json.prompt, consent: true, host: info.json.provider.host });
  assert.equal(gen.status, 201, gen.text);
  assert.equal((await app.post(`/api/books/${BOOK}/ai/cover-use`, { name: gen.json.draft.name })).status, 200);

  // ---- a webhook delivery (a scene save), then exports and the backup
  const now = await getScene(app, ARRIVAL);
  const saved = await app.put(`/api/books/${BOOK}/scenes/${ARRIVAL}/body`, { body: `${now.body}\nA line added to trigger a webhook.\n`, base_sha256: now.sha256 });
  assert.equal(saved.status, 200, saved.text);
  await until(() => receiver.deliveries.length >= 1, 'a webhook delivery');

  const downloads = [];
  for (const format of FORMATS) downloads.push({ label: `export ${format}`, ...(await getBytes(app.port, `/api/books/${BOOK}/export?format=${format}`)) });
  for (const include of ['summary', 'evidence']) downloads.push({ label: `export markdown include=${include}`, ...(await getBytes(app.port, `/api/books/${BOOK}/export?format=markdown&include=${include}`)) });
  const backup = await getBytes(app.port, `/api/books/${BOOK}/backup?provenance=1`);
  downloads.push({ label: 'backup with provenance', ...backup });
  for (const d of downloads) assert.equal(d.status, 200, d.label);
  const backupNames = [...zipContents(backup.bytes).keys()];

  await app.stop();

  return { KEY, KEY_IMG, WEBHOOK_SECRET, secrets, library, home, app, receiver, createResponse, downloads, backupNames, chat, pictures };
}

for (const run of RUNS) {
  test(`secret scan, ${run.name}: the keys appear nowhere but (for config) the settings file, and only as ciphertext in secrets.json`, async (t) => {
    const s = await fullSession(run);
    const { secrets, library, home } = s;

    // the session really did things the scan must cover (so "nothing found" is not vacuous)
    assert.ok(s.chat.chats().length >= 3, 'chat, streamed chat and rewrite reached the provider');
    assert.ok(s.chat.chats().every((c) => c.headers.authorization === `Bearer ${s.KEY}`), 'the key is sent to its provider, as a header');
    assert.equal(s.pictures.posts().length, 1);
    assert.equal(s.pictures.posts()[0].headers.authorization, `Bearer ${s.KEY_IMG}`);
    assert.ok(s.receiver.deliveries.length >= 1);
    assert.ok(s.receiver.deliveries.every((d) => s.receiver.verifies(d, s.WEBHOOK_SECRET)), 'webhooks are signed with the secret read back from the key store');
    const tree = [...(await readEverything(library)).keys()];
    assert.ok(tree.some((p) => p.startsWith('ai/')), 'AI records exist');
    assert.ok(tree.some((p) => p.startsWith('provenance/')), 'receipts exist');
    assert.ok(tree.some((p) => p.startsWith('assets/drafts/') && p.endsWith('.png')), 'a cover draft exists');
    assert.ok(tree.includes('activity/ai-usage.md'), 'the usage table exists');
    assert.ok(s.backupNames.some((n) => n.includes('provenance/')), 'the backup holds provenance');
    assert.ok(s.backupNames.some((n) => n.includes('ai/')), 'the backup holds the AI records');

    for (const secret of secrets) {
      // library files (receipts, AI records, suggestions, drafts, activity: everything), .storyforge included
      assert.deepEqual(await filesHolding(library, secret), [], 'library');
      // server stdout and stderr
      assert.equal(s.app.output().includes(secret), false, 'stdout / stderr');
      // every API response of the session (the webhook secret is shown once, in its creation response)
      for (const r of s.app.seen) {
        if (secret === s.WEBHOOK_SECRET && r === s.createResponse) continue;
        assert.equal(holds(Buffer.from(r.text), secret), false, `API response ${r.where}`);
      }
      // exports and the backup, and what is inside them
      for (const d of s.downloads) {
        assert.equal(holds(d.bytes, secret), false, d.label);
        if (/docx|epub|evidence|backup/.test(d.label) || d.bytes.subarray(0, 2).toString('latin1') === 'PK') {
          let entries;
          try {
            entries = zipContents(d.bytes);
          } catch {
            entries = null; // not a zip
          }
          for (const [name, bytes] of entries ?? []) assert.equal(holds(bytes, secret), false, `${d.label}: ${name}`);
        }
      }
    }

    // the user config folder (where the settings and the key store live)
    const config = await readConfigFiles(path.join(home.home, process.platform === 'win32' ? 'AppData' : 'xdg', process.platform === 'win32' ? 'StoryForge' : 'storyforge'));
    const holding = (needle) => Object.entries(config).filter(([, text]) => holds(Buffer.from(text), needle)).map(([name]) => name);
    if (run.storage === 'config') {
      assert.deepEqual(holding(s.KEY), ['ai.json'], 'plain text only in the settings file, as the warning says');
      assert.deepEqual(holding(s.KEY_IMG), ['ai.json']);
      assert.equal('secrets.json' in config && holds(Buffer.from(config['secrets.json']), s.KEY), false);
    } else {
      assert.deepEqual(holding(s.KEY), [], 'no config file holds the chat key');
      assert.deepEqual(holding(s.KEY_IMG), [], 'no config file holds the image key');
    }
    assert.deepEqual(holding(s.WEBHOOK_SECRET), [], 'no config file holds the webhook secret (webhooks.json has none)');
    assert.ok('webhooks.json' in config && !config['webhooks.json'].includes('"secret":'), 'webhooks.json holds no secret field');
    if (run.storage === 'secure') {
      const store = JSON.parse(config['secrets.json']);
      const ids = Object.keys(store.entries);
      assert.ok(ids.some((id) => id.startsWith('ai.')) && ids.some((id) => id.startsWith('webhook.')), `AI keys and webhook secrets both go to the key store (${ids.join(', ')})`);
      const algs = new Set(Object.values(store.entries).map((e) => e.alg));
      if (run.native && process.platform === 'win32') assert.deepEqual([...algs], ['dpapi'], 'DPAPI ciphertext on Windows');
      if (run.alg) assert.deepEqual([...algs], [run.alg]);
      if (run.keyFile !== undefined) assert.equal('secrets-key.json' in config, run.keyFile, 'the key file exists only when STORYFORGE_SECRETS_KEY is not used');
      t.diagnostic(`backend ${[...algs].join(',')}`);
    }
  });
}

test('secret scan, shared mode: the shared-data folder (members, shares, audit, key store) and the library hold no key', async () => {
  const prior = process.env.STORYFORGE_SECRETS_BACKEND;
  process.env.STORYFORGE_SECRETS_BACKEND = 'file-key'; // the server of this test runs in this process
  try {
    const t = await bootShared();
    const KEY = fakeKey('shared');
    const mock = await startProvider({ reply: REWRITTEN });
    const receiver = await startReceiver();
    const owner = (method, p, body) => t.call(method, p, { cookie: t.c.owner, ...(body === undefined ? {} : { body }) });
    const created = await owner('POST', '/api/ai/profiles', { name: 'Shared chat', model: 'mock-model-a', baseUrl: mock.baseUrl, keyStorage: 'config', apiKey: KEY });
    assert.equal(created.status, 201, created.text);
    // "Move key to secure storage" in shared mode: audited, and the plain copy is gone afterwards
    const moved = await owner('POST', `/api/ai/profiles/${created.json.profile.id}/secure`, {});
    assert.equal(moved.status, 200, moved.text);
    assert.equal(moved.json.profile.keyStorage, 'secure');
    assert.equal((await owner('PUT', `/api/books/${BOOK}/ai/profile`, { profileId: created.json.profile.id })).status, 200);
    const hook = await owner('POST', '/api/webhooks', { url: receiver.url, events: ['scene.saved'], books: 'all' });
    assert.equal(hook.status, 201, hook.text);
    const pv = await owner('POST', AI.context(), { task: 'chat', files: ['book.md'], instruction: 'Hello' });
    assert.equal(pv.status, 200, pv.text);
    assert.equal((await owner('POST', AI.send(), { contextId: pv.json.contextId })).status, 200);
    assert.equal(mock.chats()[0].headers.authorization, `Bearer ${KEY}`);

    const everything = [];
    for (const dir of [t.dir, t.root]) everything.push(...(await filesHolding(dir, KEY)), ...(await filesHolding(dir, hook.json.secret)));
    assert.deepEqual(everything, [], 'neither the AI key nor the webhook secret is in the shared data or the library');
    const shared = await fs.readdir(t.dir);
    assert.ok(shared.includes('secrets.json'), `the key store lives in the shared-data folder (${shared.join(', ')})`);
    const audit = (await Promise.all(shared.map((f) => fs.readFile(path.join(t.dir, f), 'utf8').catch(() => '')))).join('\n');
    assert.match(audit, /ai-profile-secure/, 'moving a key to secure storage is in the audit trail');
    assert.equal(audit.includes(KEY), false);
  } finally {
    if (prior === undefined) delete process.env.STORYFORGE_SECRETS_BACKEND;
    else process.env.STORYFORGE_SECRETS_BACKEND = prior;
  }
});

test('the scan itself has teeth: a key planted in a library file, in plain / base64 / URL form, or inside a zip is found', async () => {
  const { writeZip } = await import('../../../packages/export/src/index.mjs');
  const KEY = fakeKey('control');
  const dir = await freshLibrary();
  await fs.writeFile(path.join(dir, 'planted.txt'), `x ${Buffer.from(KEY).toString('base64')} y`);
  await fs.mkdir(path.join(dir, '.storyforge'), { recursive: true });
  await fs.writeFile(path.join(dir, '.storyforge', 'planted.json'), JSON.stringify({ k: encodeURIComponent(KEY) }));
  assert.deepEqual((await filesHolding(dir, KEY)).sort(), ['.storyforge/planted.json', 'planted.txt']);
  const zip = writeZip([{ name: 'inner/file.md', data: Buffer.from(`token ${KEY}`) }]);
  assert.equal(holds(zipContents(zip).get('inner/file.md'), KEY), true);
});
